import {useSelector} from "react-redux";
import BookItem from "../components/BookItem";
import './Library.css'
import React from "react";

// Import backgrounds
import desktopBg from '../images/1773005.jpg';
import mobileBg from '../images/1268196.jpg';

function Library(){
   const books = useSelector(state => state.project.books);
   const bgImage = window.innerWidth > 1023 ? desktopBg : mobileBg;

   const bookList = books.map((book) => {
       return <BookItem key={book.id} id={book.id} title={book.title} image={book.image} />
   });

    return (
        <div 
            className="library-page-container"
            style={{ 
                backgroundImage: `linear-gradient(rgba(18, 18, 18, 0.8), rgba(18, 18, 18, 0.95)), url(${bgImage})` 
            }}
        >
            <div className="library-content-wrapper">
                <h1 id="fave-book-text">Favourite Books of All Time</h1>
                <div id='book-grid'>
                    {bookList}
                </div>
            </div>
        </div>
    )
}

export default React.memo(Library);